        foreach(var section in Enum.GetValues<SwordShieldDataSection>())
        {
            Console.WriteLine("READ "+section);var rows=project.ReadData(section);Check(rows.Count>0,"Switch_Real_Read_"+section);foreach(var path in rows.Select(c=>c.Resource).Distinct()){string full=Path.Combine(root,"romfs",path);sourceHashes[full]=Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(full)));}
            var preview=project.PreviewData(section,null,new(12345));Check(preview.Result.Changes.Count>0,"Switch_Real_RandomPreview_"+section);var repeat=project.PreviewData(section,null,new(12345));Check(preview.Result.Files().All(p=>repeat.Result.Files()[p.Key].SequenceEqual(p.Value)),"Switch_Real_Deterministic_"+section);project.ApplyData(preview);Check(project.DataHistory.Last().Section==section,"Switch_Real_History_"+section);bool stale=false;try{project.ApplyData(repeat);}catch(InvalidOperationException){stale=true;}Check(stale,"Switch_Real_RejectStale_"+section);
        }
        var result=project.Export(output,SwitchModLayout.Ryujinx);using var manifest=JsonDocument.Parse(File.ReadAllText(Path.Combine(output,"definitive-mod.json")));Check(manifest.RootElement.GetProperty("DataEditors").GetArrayLength()==10,"Switch_Real_ManifestContainsTenDataEditors");foreach(var resource in manifest.RootElement.GetProperty("Resources").EnumerateArray()){string file=Path.Combine(output,resource.GetProperty("Resource").GetString()!);Check(File.Exists(file)&&Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file)))==resource.GetProperty("ResultSha256").GetString(),"Switch_Real_ExportHash_"+resource.GetProperty("Resource").GetString()!.Replace('/','_'));}
        var runtime=SwordShieldProject.Open(root);runtime.ApplyPokeFeur(runtime.PreviewPokeFeur(null,new PokeFeurOptions{Randomizer=true}));string sd=output+"-sd";Directory.CreateDirectory(sd);var diagnostic=PokeFeurSdInstall.Preview(sd,"[randomizer]\nactive = true\nbattle_pool = [1, 4, 7]\nseed = 20261022\n",root);PokeFeurSdInstall.Apply(diagnostic,false);byte[] oldSd=File.ReadAllBytes(diagnostic.Destination);Check(runtime.RuntimeSdStatus(sd).Contains("ATENCIÓN")&&runtime.RuntimeSdStatus(sd).Contains("664")&&File.ReadAllBytes(diagnostic.Destination).SequenceEqual(oldSd),"Switch_Real_SdMismatchDetectsThreeSpeciesDiagnosticConfig");var sdPlan=runtime.PreviewPokeSd(sd);runtime.InstallPokeSd(sdPlan,true);Check(runtime.RuntimeSdStatus(sd).Contains("coincide")&&File.ReadAllBytes(sdPlan.Backup!).SequenceEqual(oldSd)&&File.ReadAllText(sdPlan.Destination).Contains("battle_pool = [1, 2, 3"),"Switch_Real_SdInstallReplacesDiagnosticPoolWithBackup");
        runtime.ApplyPokeFeur(runtime.PreviewPokeFeur(null,runtime.PokeFeurCurrent! with{Caps=true,CapsFromTrainers=true}));var bossLevel=runtime.ReadData(SwordShieldDataSection.TrainerTeams).First(c=>c.Entry==32&&c.Field=="Nivel");runtime.ApplyData(runtime.PreviewData(SwordShieldDataSection.TrainerTeams,new[]{new SwordShieldDataEdit(bossLevel.Key,100)}));bool capRejected=false;try{runtime.Export(output+"-stale-caps",SwitchModLayout.Ryujinx);}catch(InvalidOperationException e)when(e.Message.Contains("jefes")){capRejected=true;}Check(capRejected&&!Directory.Exists(output+"-stale-caps"),"Switch_Real_ManualBossLevelInvalidatesAutomaticCapsExport");runtime.ApplyPokeFeur(runtime.PreviewPokeFeur(null,runtime.PokeFeurCurrent!));Check(runtime.PokeFeurCurrent!.StoryCaps[0]==100,"Switch_Real_UpdatingCapsUsesEditedTrainerLevels");
        Check(sourceHashes.All(p=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p.Key)))==p.Value),"Switch_Real_AllSourcesUnchanged");project.Reset();Check(!project.HasChanges&&project.DataHistory.Count==0&&project.RevisionHash==initial,"Switch_Real_ResetClearsAdvancedEdits");Console.WriteLine($"Completed {count} Switch expansion integration checks; source read-only, gameplay NOT tested.");
